import csv,re,collections,glob
for f in glob.glob('saida/*.csv'):
    b=open(f,'rb').read()
    try: b.decode('utf-8'); e='utf8'
    except Exception as x: e='NAO utf8'
    print(f,e,b[:3],b.count(b'\r\n'))
def rd(f): return list(csv.DictReader(open(f,encoding='utf-8',errors='replace'),delimiter=';'))
for f in ['comissoes_por_lojista','divergencias_taxa','lancamentos_classificados']:
    r=rd(f'saida/{f}.csv')
    for k in r[0]:
        if 'cnpj' in k: print(f,k,collections.Counter(len(x[k]) for x in r))
ra=rd('saida/rastro.csv'); ids=collections.defaultdict(float)
for x in ra: ids[x['id_saida']]+=float(x['valor'])
for f,c in [('comissoes_por_lojista','comissao_brl'),('divergencias_taxa','diferenca_brl'),('lancamentos_classificados','valor')]:
    bad=[(x['id_saida'],x[c],round(ids.get(x['id_saida'],-999),2)) for x in rd(f'saida/{f}.csv') if abs(float(x[c])-ids.get(x['id_saida'],-999))>0.005]
    print(f,len(bad),bad[:6])
print(collections.Counter(x['arquivo_origem'] for x in ra))
l=rd('saida/lancamentos_classificados.csv'); print(l[0]); print(collections.Counter(x['metodo'] for x in l)); print(sum(1 for x in l if not x['conta_codigo']))
E
grep -n -i "iss\b\|ISS " REGRAS_NEGOCIO.md HIPOTESES.md PLANO.md | head -20; grep -n -i "razão social\|razao social" REGRAS_NEGOCIO.md HIPOTESES.md | head; grep -rn -i "fluente" HIPOTESES.md REGRAS_NEGOCIO.md | head -8

